def hidden_rule_fn(state):
    def signed_delta(from_pos, to_pos, size=8):
        d = (to_pos - from_pos) % size
        if d > size // 2:
            d -= size
        return d

    def toroidal_dist(p, q):
        dx = abs(signed_delta(p['x'], q['x']))
        dy = abs(signed_delta(p['y'], q['y']))
        penalty = 0 if p['type'] == q['type'] else 1
        return max(dx, dy) + penalty

    def find_nearest(particle, candidates, target_type):
        others = [c for c in candidates if c['type'] == target_type and c is not particle]
        if not others:
            return None
        return min(others, key=lambda c: (toroidal_dist(particle, c), c['x'], c['y']))

    def step_toward(px, py, tx, ty):
        sdx = signed_delta(px, tx)
        sdy = signed_delta(py, ty)
        nx = (px + (1 if sdx > 0 else -1 if sdx < 0 else 0)) % 8
        ny = (py + (1 if sdy > 0 else -1 if sdy < 0 else 0)) % 8
        return nx, ny

    def flee_from(px, py, ex, ey):
        sdx = signed_delta(px, ex)
        sdy = signed_delta(py, ey)
        if abs(sdx) >= abs(sdy):
            nx = (px + (-1 if sdx > 0 else 1 if sdx < 0 else 0)) % 8
            ny = py
        else:
            nx = px
            ny = (py + (-1 if sdy > 0 else 1 if sdy < 0 else 0)) % 8
        return nx, ny

    next_state = []
    for particle in state:
        if particle['type'] == 'ZEX':
            partner = find_nearest(particle, state, 'ZEX')
            if partner is None:
                next_state.append({'type': 'ZEX', 'x': particle['x'], 'y': particle['y']})
            else:
                nx, ny = step_toward(particle['x'], particle['y'], partner['x'], partner['y'])
                next_state.append({'type': 'ZEX', 'x': nx, 'y': ny})
        else:
            enemy = find_nearest(particle, state, 'ZEX')
            if enemy is None:
                next_state.append({'type': 'GLORP', 'x': particle['x'], 'y': particle['y']})
            else:
                nx, ny = flee_from(particle['x'], particle['y'], enemy['x'], enemy['y'])
                next_state.append({'type': 'GLORP', 'x': nx, 'y': ny})
    return next_state

def hidden_rule_fn(state):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    n = len(state)
    if is_prime(n):
        new_val = (state[-1] ^ state[-2]) % 7
    else:
        new_val = (state[-1] + state[-2] + 3) % 7

    return state + [new_val]

def hidden_rule_fn(state):
    result = [0] * 15
    # Row 0 (even): new[c] = (v + right_neighbour) mod 5, wraps within row
    for c in range(5):
        result[c] = (state[c] + state[(c + 1) % 5]) % 5
    # Row 1 (odd): new[c] = (v XOR cell_below) mod 5
    for c in range(5):
        result[5 + c] = (state[5 + c] ^ state[10 + c]) % 5
    # Row 2 (even): new[c] = (v + right_neighbour) mod 5, wraps within row
    for c in range(5):
        result[10 + c] = (state[10 + c] + state[10 + (c + 1) % 5]) % 5
    return result

def hidden_rule_fn(state):
    n = len(state)
    digit_sum = sum(int(d) for d in str(n))
    last = state[-1]
    second_last = state[-2]
    mod = digit_sum % 3
    if mod == 0:
        new_val = (last + second_last) % 11
    elif mod == 1:
        new_val = (last ^ second_last) % 11
    else:
        new_val = (last * second_last) % 11
    return state + [new_val]

def hidden_rule_fn(state):
    n = len(state)
    wc = n % 4
    if wc == 3:
        new = (state[-1] - state[-3]) % 13
    elif wc == 0:
        new = (state[-1] + state[-3]) % 13
    elif wc == 1:
        new = (state[-3] - state[-2] - state[-1]) % 13
    else:  # wc == 2
        new = (3 * state[-2] + state[-1]) % 13
    return state + [new]

def hidden_rule_fn(state):
    n = len(state)
    last = state[-1]
    second = state[-2] if len(state) >= 2 else 0

    def is_perfect_square(x):
        if x < 0:
            return False
        root = int(x ** 0.5)
        return root * root == x

    if is_perfect_square(n):
        new_val = (last >> 1) ^ second
    elif n % 3 == 0:
        new_val = (last + second + n) % 16
    else:
        new_val = ((last << 1) & 0xF) | (second & 1)

    return state + [new_val]
